// بناء رسالة الرد حسب نوع العملية
const data = $input.first().json;
const now = new Date();
const timeStr = now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit', hour12: false });
const dateStr = now.toLocaleDateString('ar-EG', { day: '2-digit', month: '2-digit', year: 'numeric' });

if (!data.success) {
  return [{ json: {
    to: data.from_number,
    message: `❌ حدث خطأ أثناء تسجيل العملية في النظام.\nيرجى التواصل مع المحاسب.\n\n🕐 ${timeStr} — ${dateStr}`
  }}];
}

const type = data.transaction_type;
const ref  = data.ref_number;
const amount = new Intl.NumberFormat('ar-EG', { minimumFractionDigits: 2 }).format(data.amount || 0);

let msg = '';

if (type === 'GUEST_CHECKIN') {
  msg = [
    `✅ *تم تسجيل دخول النزيل بنجاح*`,
    ``,
    `📋 *رقم الفاتورة:* ${ref}`,
    `💰 *الإجمالي:* ${amount} جـ (شامل VAT 14%)`,
    `👤 *الاسم:* ${data.contact_name || 'N/A'}`,
    `🕐 *الوقت:* ${timeStr} — ${dateStr}`,
    ``,
    `_تم التسجيل تلقائياً في Zoho Books_`
  ].join('\n');

} else if (type === 'CAFE_SHIFT') {
  msg = [
    `✅ *تم تقفيل وردية الكافيه بنجاح*`,
    ``,
    `📋 *رقم القيد:* ${ref}`,
    `💰 *الإجمالي المحصّل:* ${amount} جـ`,
    `🕐 *الوقت:* ${timeStr} — ${dateStr}`,
    ``,
    `_تم ترحيل الإيراد وتوزيع الضرائب تلقائياً_`
  ].join('\n');

} else if (type === 'EXPENSE_BILL') {
  msg = [
    `✅ *تم تسجيل الفاتورة بنجاح*`,
    ``,
    `📋 *رقم الفاتورة:* ${ref}`,
    `💰 *إجمالي الفاتورة:* ${amount} جـ`,
    `🏷️ *تم تطبيق ضريبة الخصم (WHT)*`,
    `🕐 *الوقت:* ${timeStr} — ${dateStr}`,
    ``,
    `_تم التسجيل تلقائياً في Zoho Books_`
  ].join('\n');
}

return [{ json: {
  to: data.from_number,
  message: msg
}}];

// تسجيل نجاح الإرسال
const msg_id = $input.first().json.messages?.[0]?.id;
console.log(`[${new Date().toISOString()}] WhatsApp reply sent: ${msg_id}`);
return [{ json: { status: 'sent', message_id: msg_id } }];

// تسجيل فشل الإرسال
const error = $input.first().json;
console.error(`[${new Date().toISOString()}] WhatsApp reply FAILED:`, JSON.stringify(error));
return [{ json: { status: 'failed', error } }];
